mapper.select:
SELECT cr.CITIZEN_REPORT_ID AS citizenReportId, cr.CATEGORY AS category, cr.DESCRIPTION AS description, cr.EMAIL AS email, cr.STATUS AS status, cr.CREATED_AT AS createdAt, cr.RESOLVED_BY AS resolvedBy, cr.RESOLVED_AT AS resolvedAt, cr.FACILITY_ID AS facilityId, f.NAME AS name, f.FLOOR AS floor, f.ZONE AS zone, f.ADDRESS AS address FROM CITIZEN_REPORTS cr JOIN FACILITIES f ON f.FACILITY_ID = cr.FACILITY_ID
f.MANAGERS_ID = #{managerId}
AND cr.STATUS = #{status}
AND cr.CREATED_AT >= #{fromDt}
AND cr.CREATED_AT < #{toExclusive}
AND ( UPPER(f.NAME) LIKE UPPER('%' || #{q} || '%') OR UPPER(cr.CATEGORY) LIKE UPPER('%' || #{q} || '%') OR UPPER(cr.EMAIL) LIKE UPPER('%' || #{q} || '%') OR (cr.DESCRIPTION IS NOT NULL AND DBMS_LOB.INSTR(LOWER(cr.DESCRIPTION), LOWER(#{q})) > 0) )
ORDER BY cr.CREATED_AT DESC

mapper.delete:
DELETE FROM CITIZEN_REPORTS cr
WHERE cr.CITIZEN_REPORT_ID = #{id}
  AND EXISTS (
    SELECT 1
    FROM FACILITIES f
    WHERE f.FACILITY_ID = cr.FACILITY_ID
      AND f.MANAGERS_ID = #{managerId}
  )
